on conflict(content_version_id,task_key,task_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p1_aw21_24_integration_apps_v1' and status='draft'), defs(k,t,en,ru,uz) as (values
('p1_aw21_int_apps_diagnostic','diagnostic','P1 AW21-24 Integration applications diagnostic','Диагностика P1 AW21–24: применения интегрирования','P1 AW21–24 integrallash qo‘llanishi diagnostikasi'),
('p1_int04_learning','learning','Areas by integration learning','Площади интегрированием: обучение','Integral bilan yuza: o‘rganish'),
('p1_int05_learning','learning','Volumes of revolution learning','Объёмы вращения: обучение','Aylanish hajmi: o‘rganish'),
('p1_int04_retest','retest','INT-04 delayed retest','INT-04 отложенный ретест','INT-04 kechiktirilgan retest'),
('p1_int05_retest','retest','INT-05 delayed retest','INT-05 отложенный ретест','INT-05 kechiktirilgan retest'),
